async function executeGenerateVideo(options, input) {
  const { prompt, modelId, aspectRatio, duration, videoSubMode, imageUrl, referenceVideoUrl } = input;
  try {
    const res = await callInternalApi("/api/v1/generate-video", {
      prompt,
      modelId,
      aspectRatio,
      duration,
      videoSubMode,
      imageUrl: imageUrl ?? referenceVideoUrl,
      conversationId: options.conversationId,
      turnId: options.turnId,
      ...toolAuthBody(options)
    }, options.accessToken, options.baseUrl, {
      forwardCookie: options.forwardCookie
    });
    if (!res.ok) {
      const err = await res.json().catch((_error) => ({
        message: "Unknown error"
      }));
      return {
        success: false,
        status: "failed",
        error: err.message ?? "Video generation failed"
      };
    }
    const reader = res.body?.getReader();
    if (!reader) {
      return {
        success: false,
        status: "failed",
        error: "No response stream"
      };
    }
    const decoder = new TextDecoder();
    let buffer = "";
    let outputId = null;
    let finalResult = null;
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, {
        stream: true
      });
      const lines = buffer.split("\n\n");
      buffer = lines.pop() ?? "";
      for (const line of lines) {
        if (!line.startsWith("data: ")) continue;
        try {
          const event = JSON.parse(line.slice(6));
          if (event.type === "started") {
            outputId = event.outputId;
          } else if (event.type === "completed") {
            finalResult = event;
          } else if (event.type === "failed") {
            return {
              success: false,
              status: "failed",
              outputId: outputId ?? event.outputId,
              error: event.error
            };
          }
        } catch (_error) {
        }
      }
    }
    if (finalResult) {
      return {
        success: true,
        status: "completed",
        outputId: finalResult.outputId,
        modelUsed: finalResult.modelUsed,
        message: `Video generated successfully with ${finalResult.modelUsed}. OutputId: ${finalResult.outputId}`
      };
    }
    return {
      success: true,
      status: "pending",
      outputId,
      message: `Video generation started (outputId: ${outputId}). It will appear in the Outputs tab when complete.`
    };
  } catch (err) {
    return {
      success: false,
      status: "failed",
      error: err instanceof Error ? err.message : "Video generation failed"
    };
  }
}
